#!/usr/bin/env node
'use strict';

/*
 * tools/sample-tests.js
 * CPH-style sample self-test with scoring, independent of the CPH extension.
 *
 *   node tools/sample-tests.js --list <problem.cpp>   # read tests only (JSON)
 *   node tools/sample-tests.js <problem.cpp>          # compile + run all tests (JSON)
 *
 * Sample data is read from:
 *   1. sibling <problem>.json  (generated by pull-contest.js; {tests:[{input,output}]})
 *   2. .cph/.<file>_<hash>.prob next to the source (CPH/legacy cache)
 *
 * Output is one JSON object on stdout:
 *   list: { cpp, source, timeLimitMs, tests:[{index,input,output}] }
 *   run:  { cpp, source, compiled, compileError, tests:[{index,input,output,status,ms,got}],
 *           passed, total, score, maxScore }
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { spawnSync } = require('child_process');

const ROOT = path.resolve(__dirname, '..');
const BUILD = path.join(ROOT, '.build', 'sample-tests');

function fail(msg, code) {
    console.error(msg);
    process.exit(code || 1);
}

function readJson(file) {
    try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch (e) { return null; }
}

function normalize(s) {
    const lines = String(s == null ? '' : s).replace(/\r\n?/g, '\n').split('\n');
    return lines.map(function (line) { return line.replace(/[ \t]+$/, ''); })
        .join('\n').replace(/\n+$/, '');
}

function findSamples(cpp) {
    const dir = path.dirname(cpp);
    const base = path.basename(cpp);
    const stem = base.replace(/\.(cpp|cc|cxx)$/i, '');

    // 1) our own structured data file
    const dataFile = path.join(dir, stem + '.json');
    const data = readJson(dataFile);
    if (data && Array.isArray(data.tests) && data.tests.length) {
        return {
            source: dataFile,
            timeLimitMs: Number(data.timeLimitMs) || 2000,
            memoryLimitMb: Number(data.memoryLimitMb) || 256,
            tests: data.tests.map(function (t) {
                return { input: String(t.input == null ? '' : t.input), output: String(t.output == null ? '' : t.output) };
            })
        };
    }

    // 2) CPH cache next to source: .cph/.<file>_<hash>.prob
    const cphDir = path.join(dir, '.cph');
    if (fs.existsSync(cphDir)) {
        const prefix = '.' + base + '_';
        const files = fs.readdirSync(cphDir).filter(function (f) {
            return f.indexOf(prefix) === 0 && /\.prob$/i.test(f);
        }).map(function (f) {
            const p = path.join(cphDir, f);
            let mtime = 0;
            try { mtime = fs.statSync(p).mtimeMs; } catch (e) { /* ignore */ }
            return { path: p, mtime: mtime };
        }).sort(function (a, b) { return b.mtime - a.mtime; });
        for (let i = 0; i < files.length; i++) {
            const prob = readJson(files[i].path);
            if (prob && Array.isArray(prob.tests) && prob.tests.length) {
                return {
                    source: files[i].path,
                    timeLimitMs: Number(prob.timeLimit) || 2000,
                    memoryLimitMb: Number(prob.memoryLimit) || 256,
                    tests: prob.tests.map(function (t) {
                        return { input: String(t.input == null ? '' : t.input), output: String(t.output == null ? '' : t.output) };
                    })
                };
            }
        }
    }
    return null;
}

function main() {
    const args = process.argv.slice(2);
    const listOnly = args.indexOf('--list') >= 0;
    const rest = args.filter(function (a) { return a !== '--list'; });
    const cpp = rest[0] ? path.resolve(ROOT, rest[0]) : '';
    if (!cpp || !fs.existsSync(cpp)) fail('usage: node tools/sample-tests.js [--list] <problem.cpp>');
    const samples = findSamples(cpp);
    if (!samples) {
        console.log(JSON.stringify({ cpp: cpp, source: '', tests: [], error: '没有找到样例（同目录 .json 或 .cph 缓存）' }));
        return 0;
    }

    if (listOnly) {
        console.log(JSON.stringify({
            cpp: cpp,
            source: samples.source,
            timeLimitMs: samples.timeLimitMs,
            tests: samples.tests.map(function (t, i) {
                return { index: i + 1, input: t.input, output: t.output };
            })
        }));
        return 0;
    }

    fs.mkdirSync(BUILD, { recursive: true });
    const hash = crypto.createHash('md5').update(cpp).digest('hex').slice(0, 10);
    const exe = path.join(BUILD, 'sol-' + hash + '.exe');

    const compile = spawnSync('g++', [
        cpp, '-o', exe,
        '-std=gnu++23', '-O2', '-Wl,--stack,268435456',
        '-D', 'DEBUG', '-D', 'CPH'
    ], { encoding: 'utf8', timeout: 180000, windowsHide: true, maxBuffer: 32 * 1024 * 1024 });

    if (compile.error || compile.status !== 0) {
        console.log(JSON.stringify({
            cpp: cpp,
            source: samples.source,
            compiled: false,
            compileError: String((compile.stderr || '') + (compile.error ? compile.error.message : '')).slice(-4000),
            tests: [],
            passed: 0,
            total: samples.tests.length,
            score: 0,
            maxScore: samples.tests.length
        }));
        return 0;
    }

    const results = [];
    let passed = 0;
    const tl = Math.max(500, samples.timeLimitMs || 2000);
    samples.tests.forEach(function (t, i) {
        const started = process.hrtime.bigint();
        const r = spawnSync(exe, [], {
            input: t.input,
            encoding: 'utf8',
            timeout: tl * 2 + 1000,
            windowsHide: true,
            maxBuffer: 64 * 1024 * 1024
        });
        const ms = Number(process.hrtime.bigint() - started) / 1e6;
        let status = 'PASS';
        if (r.error && r.error.code === 'ETIMEDOUT') status = 'TLE';
        else if (r.status !== 0) status = 'RE';
        else if (normalize(r.stdout) !== normalize(t.output)) status = 'FAIL';
        if (status === 'PASS') passed++;
        results.push({
            index: i + 1,
            input: t.input,
            output: t.output,
            status: status,
            ms: Math.round(ms),
            got: r.stdout == null ? '' : String(r.stdout)
        });
    });

    console.log(JSON.stringify({
        cpp: cpp,
        source: samples.source,
        compiled: true,
        compileError: '',
        tests: results,
        passed: passed,
        total: samples.tests.length,
        score: passed,
        maxScore: samples.tests.length
    }));
    return 0;
}

process.exit(main());
